+                                              &server_opcode_vals_ext,
+                                              "Opcode 0x%x"),
+                               request ? "Request" : "Response");
+      break;
+
+    case SERVER_OPCODE_GET_AUTHORIZATION:
+      if (!request) {
+          expert_add_info_format(pinfo, ti, &ef_warn_shall_not_have_key,
+                                 "GetAuthorization response shall not have key");
+      }
+      break;
+    default:
+      break;
+  }
+}
